import json, collections
from pipeline.eval2_leaks import bank_leaks
cases = {c["case_id"]: c for c in (json.loads(l) for l in open("work/eval2/bank-all/bank.jsonl"))}
e2 = [json.loads(l) for l in open("work/eval2/split/eval2.jsonl")]
tr = [json.loads(l) for l in open("work/eval2/split/train.jsonl")]
rep = bank_leaks(e2, tr)
print("pairs:", rep["pairs"] and len(rep["pairs"]), "| by_rule:", rep["by_rule"])
shared = collections.Counter()
for p in rep["pairs"]:
    a, b = cases[p["eval2_id"]], cases[p["other_id"]]
    common = {t["stdout"] for t in a["tests"]} & {t["stdout"] for t in b["tests"]}
    for s in common: shared[s] += 1
    print(" ", p["eval2_id"], a["family"], "<->", p["other_id"], b["family"], "|", [repr(s)[:50] for s in common])
# Unify: give every case in a leaking pair the same source_group (union-find over pairs), write a unified bank.
parent = {}
def find(x):
    while parent.get(x, x) != x: x = parent[x]
    return x
def union(a, b):
    ra, rb = find(a), find(b)
    if ra != rb: parent[ra] = rb
for p in rep["pairs"]: union(p["eval2_id"], p["other_id"])
groups = collections.defaultdict(list)
for cid in cases:
    if cid in parent or any(cid == p["other_id"] or cid == p["eval2_id"] for p in rep["pairs"]): groups[find(cid)].append(cid)
n = 0
for root, members in groups.items():
    sg = "unified-" + root
    for cid in members:
        cases[cid]["source_group"] = sg; n += 1
with open("work/eval2/bank-all/bank-unified.jsonl", "w") as f:
    for cid in sorted(cases): f.write(json.dumps(cases[cid], sort_keys=True, ensure_ascii=False) + "\n")
print("unified", n, "cases into", len(groups), "groups")

